const cfg = $input.first()?.json || {};
const errors = [];

function cleanUrl(value) {
  return String(value || '').trim().replace(/\/+$/, '');
}

const opsApiUrl = cleanUrl(cfg.opsApiUrl);
const agentToken = String(cfg.agentToken || '').trim();
const limit = Math.min(Math.max(Number(cfg.limit || 50), 1), 100);

if (!/^https:\/\//i.test(opsApiUrl)) errors.push('NEONTRIP_OPS_BASE_URL/opsApiUrl must resolve to an https URL');
if (!agentToken) errors.push('OPS_INTERNAL_API_KEY/QUOTE_INTERNAL_API_TOKEN/SUPPLIER_SALES_AGENT_API_TOKEN/NEONTRIP_OFFERS_INTERNAL_API_KEY missing');
if (!Number.isFinite(limit) || limit < 1 || limit > 100) errors.push('limit must be 1..100');

if (errors.length) {
  throw new Error('Supplier Completed Offers Sync config failed: ' + errors.join('; '));
}

return [{
  json: {
    opsApiUrl,
    limit,
    authorizationHeader: 'Bearer ' + agentToken,
    correlationId: 'supplier-completed-offers-sync:' + new Date().toISOString()
  }
}];

const payload = $input.first()?.json || {};
const alerts = Array.isArray(payload.completedOffersSync?.watchdogAlerts) ? payload.completedOffersSync.watchdogAlerts : [];
if (!alerts.length) return [];

function text(value, max = 240) {
  return String(value ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
}
function html(value) {
  return text(value, 1000).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
}
function formatDate(value) {
  const date = new Date(value);
  return Number.isFinite(date.getTime()) ? date.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }) : text(value, 80);
}
function money(value) {
  const amount = Number(value);
  return Number.isFinite(amount) ? amount.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }) : 'unbekannt';
}

const rows = alerts.map((alert) => {
  const offerNumber = text(alert.offerNumber || alert.documentReference || alert.offerId || 'Unbekannt', 160);
  const salesUrl = 'https://ops.neontrip.de/ops/sales-vergabe?q=' + encodeURIComponent(offerNumber);
  return '<tr>'
    + '<td style=\"padding:8px;border:1px solid #ddd;\"><a href=\"' + html(salesUrl) + '\">' + html(offerNumber) + '</a></td>'
    + '<td style=\"padding:8px;border:1px solid #ddd;\">' + html(alert.shopifyOrderName || alert.shopifyOrderId || 'Unbekannt') + '</td>'
    + '<td style=\"padding:8px;border:1px solid #ddd;\">' + html(formatDate(alert.offerAcceptedAt)) + '</td>'
    + '<td style=\"padding:8px;border:1px solid #ddd;\">' + html(formatDate(alert.shopifyCreatedAt)) + '</td>'
    + '<td style=\"padding:8px;border:1px solid #ddd;\">' + html(money(alert.offerTotal)) + ' / ' + html(money(alert.shopifyTotal)) + '</td>'
    + '</tr>';
}).join('');

const subject = alerts.length === 1
  ? 'DRINGEND: Sales-Vergabe Shopify-Zuordnung prüfen (' + text(alerts[0].offerNumber || alerts[0].documentReference || '1 Fall', 120) + ')'
  : 'DRINGEND: ' + alerts.length + ' Sales-Vergabe Shopify-Zuordnungen prüfen';
const body = '<div style=\"font-family:Arial,sans-serif;color:#222;line-height:1.5;\">'
  + '<h2 style=\"color:#c0392b;\">Sales-Vergabe Watchdog</h2>'
  + '<p>Der automatische Abgleich hat eine Shopify-Order verknüpft, die bereits deutlich vor der Angebotsannahme existierte und zusätzlich bei Kunde und Gesamtbetrag abweicht.</p>'
  + '<p><strong>Es wurde nichts automatisch repariert.</strong> Bitte den Fall in der Sales-Vergabe manuell klären.</p>'
  + '<table style=\"border-collapse:collapse;width:100%;\"><tr style=\"background:#f4f4f4;\"><th style=\"padding:8px;border:1px solid #ddd;\">Angebot</th><th style=\"padding:8px;border:1px solid #ddd;\">Shopify</th><th style=\"padding:8px;border:1px solid #ddd;\">Annahme</th><th style=\"padding:8px;border:1px solid #ddd;\">Order erstellt</th><th style=\"padding:8px;border:1px solid #ddd;\">Beträge</th></tr>' + rows + '</table>'
  + '<p style=\"color:#666;font-size:12px;\">Interner Alarm ohne Kundendaten. Der einmalige Alarm entsteht nur beim erstmaligen Verknüpfen des unplausiblen Falls.</p>'
  + '</div>';

return [{ json: { recipient: 'info@neontrip.de', subject, body, alertCount: alerts.length } }];
